export const storePage = (key: string): StorePage => {
  const spec = pages[key]
  if (!spec) throw new Error(`no test page ${key}`)
  const { ids, ...rest } = spec
  return { ...rest, items: ids.flatMap((id) => rows[id] ?? []) }
}

